1	export type Cell = [number, number];
2	
3	const NEIGHBOR_OFFSETS: Cell[] = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [0, -1], [0, 1],
6	  [1, -1], [1, 0], [1, 1],
7	];
8	
9	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const neighborsOf = ([x, y]: Cell): Cell[] =>
12	  NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
13	
14	export function nextGeneration(cells: Cell[]): Cell[] {
15	  const living = new Set(cells.map(keyOf));
16	  const isAlive = (cell: Cell): boolean => living.has(keyOf(cell));
17	
18	  const countLiveNeighbors = (cell: Cell): number =>
19	    neighborsOf(cell).filter(isAlive).length;
20	
21	  const survivors = cells.filter((cell) => {
22	    const neighbors = countLiveNeighbors(cell);
23	    return neighbors === 2 || neighbors === 3;
24	  });
25	
26	  const births = new Map<string, Cell>();
27	  for (const cell of cells) {
28	    for (const candidate of neighborsOf(cell)) {
29	      if (isAlive(candidate)) continue;
30	      if (countLiveNeighbors(candidate) === 3) births.set(keyOf(candidate), candidate);
31	    }
32	  }
33	
34	  return [...survivors, ...births.values()];
35	}
